}

:deep(.collapsible-panel .collapsible-panel__container) {
  border-right: none;
}

:deep(.collapsible-panel .collapsible-panel__resizer) {
  display: none;
}

:deep(.collapsible-panel.is-collapsed) {
  width: 100% !important;
  min-width: 100% !important;
