  flex: 1;
  min-height: 48px;
}

/* v39: 过滤条件 badge 样式 */
.filter-badge-text {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  background: var(--color-primary-bg, #fff7ed);
